import type { FC } from 'react';
import { useMemo } from 'react';
import { useSearchParams } from 'react-router-dom';
import ShareLayout from '@/components/share/ShareLayout';
import LivePreview from '@/components/tools/contrast-checker/LivePreview';
import RatioDisplay from '@/components/tools/contrast-checker/RatioDisplay';
import ComplianceBadges from '@/components/tools/contrast-checker/ComplianceBadges';
import { decodeShareState } from '@/lib/share/encode';
import { parseHex } from '@/lib/color/convert';
import { checkWcagCompliance, getContrastRatio } from '@/lib/contrast/wcag';
import { getApcaScore } from '@/lib/contrast/apca';

interface ContrastShareState {
  bg: string;
  fg: string;
}

const ContrastCheckerShare: FC = () => {
  const [searchParams] = useSearchParams();

  const state = useMemo(() => {
    const encoded = searchParams.get('d');
    if (!encoded) return null;
    return decodeShareState<ContrastShareState>(encoded);
  }, [searchParams]);

  const bgRgb = state ? parseHex(state.bg) : null;
  const fgRgb = state ? parseHex(state.fg) : null;
  const valid = !!bgRgb && !!fgRgb;

  if (!state || !valid || !bgRgb || !fgRgb) {
    return (
      <ShareLayout title="Invalid link" toolPath="/tools/contrast-checker" toolName="Contrast Checker">
        <div className="max-w-md mx-auto text-center py-16">
          <h1 className="text-2xl font-display font-medium mb-3 text-accent">This link is broken</h1>
          <p className="text-muted-foreground">
            It's missing or malformed. Open the tool below to check a color pair and generate a fresh
            share link.
          </p>
        </div>
      </ShareLayout>
    );
  }

  const ratio = getContrastRatio(fgRgb, bgRgb);
  const apcaScore = getApcaScore(fgRgb, bgRgb);
  const compliance = checkWcagCompliance(ratio);

  return (
    <ShareLayout title="Shared contrast check" toolPath="/tools/contrast-checker" toolName="Contrast Checker">
      <div className="max-w-5xl mx-auto py-8">
        <h1 className="sr-only">Shared contrast check</h1>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 lg:gap-16 items-start">
          <div className="space-y-8">
            <div className="grid grid-cols-2 gap-4">
              <div className="text-center">
                <div
                  className="h-24 sm:h-28 rounded-xl border border-border shadow-glow"
                  style={{ backgroundColor: state.bg }}
                  aria-hidden="true"
                />
                <p className="mt-2.5 text-xs text-muted-foreground uppercase tracking-widest">Background</p>
                <p className="font-mono text-sm text-foreground">{state.bg}</p>
              </div>
              <div className="text-center">
                <div
                  className="h-24 sm:h-28 rounded-xl border border-border shadow-glow"
                  style={{ backgroundColor: state.fg }}
                  aria-hidden="true"
                />
                <p className="mt-2.5 text-xs text-muted-foreground uppercase tracking-widest">Foreground</p>
                <p className="font-mono text-sm text-foreground">{state.fg}</p>
              </div>
            </div>

            <LivePreview backgroundHex={state.bg} foregroundHex={state.fg} />
          </div>

          <div className="space-y-8">
            <div className="glass-panel hover:border-border p-6">
              <RatioDisplay ratio={ratio} apcaScore={apcaScore} />
            </div>

            <div>
              <h2 className="text-sm font-medium text-muted-foreground mb-3 text-center">WCAG 2.1 Compliance</h2>
              <ComplianceBadges compliance={compliance} />
            </div>
          </div>
        </div>
      </div>
    </ShareLayout>
  );
};

export default ContrastCheckerShare;
